INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "张天祐（郭子兴军将）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年取和阳、受宋右副元帅，攻集庆被杀。", "biography": null, "status": "draft", "id": "5bc1cc3a-538d-55e0-a5c5-80feaeaf4ede"}, {"name": "郭天叙", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "郭子兴长子，1355年继帅受宋军号、被陈埜先杀。", "biography": null, "status": "draft", "id": "cee66f31-f5f1-54d2-ac4b-cd2a49fdb40e"}, {"status": "draft", "name": "韩林儿", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "韩山童之子，父被擒后与杨氏逃武安。", "biography": null, "id": "15a71da9-cd6f-5a0b-ba68-144469ebde18"}, {"name": "韩山童", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "栾城人，承白莲会活动，倡弥勒下生，与刘福通等筹起兵事泄被擒；宋徽宗后裔仅其党宣传。", "biography": null, "status": "draft", "id": "8c55f661-a30a-53e7-840c-8dabfaa2a6ba"}, {"status": "draft", "name": "刘福通", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1351年与韩山童等筹起兵，事发后以红巾起事攻陷颍州，后攻河南多地。", "biography": null, "id": "bb43c0fa-e764-55ad-a47a-f24d9349e961"}, {"name": "常遇春", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "怀远人，1355年投朱元璋、采石先登。", "biography": null, "status": "draft", "id": "51d50a75-07e1-574f-b22d-1fded66288ff"}, {"name": "廖永安", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年领水军附朱，导舟渡江。", "biography": null, "status": "draft", "id": "473be43f-6bda-56e2-b78d-5dec54725ac0"}, {"name": "俞通海", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年导巢湖军附朱元璋，领水军渡江。", "biography": null, "status": "draft", "id": "eff73aa1-e4e3-5022-b155-bf9d88812371"}, {"name": "曼济哈雅（元南台中丞）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1353年参与攻徐寿辉蕲水。", "biography": null, "status": "draft", "id": "f03aa5ed-5240-53e8-93d7-77707427f880"}, {"name": "纳克楚（元太平万户）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "穆呼哩裔孙，1355年被朱俘后放北归。", "biography": null, "status": "draft", "id": "89f87003-83bd-5c55-b910-1c5e3f351489"}, {"name": "靳义（元太平总管）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年城陷投水死。", "biography": null, "status": "draft", "id": "45ed38fa-42f1-5777-9ec7-0d7a6001cc3c"}, {"name": "陶安", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "太平儒者，1355年劝朱据金陵，参与机密。", "biography": null, "status": "draft", "id": "e532b07c-1439-59f2-9d9e-c03e6fe1c439"}, {"name": "李习（元末太平儒者）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "迎朱元璋，1355年任太平知府。", "biography": null, "status": "draft", "id": "01e6f626-bb8d-5d6d-823c-a0bd2f17e0bb"}, {"name": "陈埜先", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "方山寨民兵元帅，1355年诈降朱军后杀郭张，后被卢德茂伏杀。", "biography": null, "status": "draft", "id": "e162f293-f1f5-514d-a501-4b1a3b7f54fb"}, {"name": "康茂才", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "水寨元帅，集庆陷后率众降朱。", "biography": null, "status": "draft", "id": "f04c265d-38f9-5b72-9c39-567870658cd2"}, {"name": "邓愈", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年从朱元璋设伏擒陈埜先。", "biography": null, "status": "draft", "id": "5fbf3347-c8f3-5eaa-aa83-d0681e64b192"}, {"name": "兆先（陈埜先子）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年父死后聚军方山。", "biography": null, "status": "draft", "id": "327fe3e3-2043-5c74-9aaa-aa96fbd51ac3"}, {"name": "福寿（元淮南平章）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "元臣，1352年由也可札鲁忽赤转淮南行省平章；本书额楚克达噜噶齐与元史官称异字保留，不造额楚克地名。", "biography": null, "status": "draft", "id": "988fcd01-fe5e-558d-b908-845e059916ba"}, {"name": "夏煜", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "朱元璋下集庆后录用儒士。", "biography": null, "status": "draft", "id": "033b7a2f-3cb8-51a8-9132-06909c2af1c5"}, {"name": "孙炎", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "朱元璋下集庆后录用儒士。", "biography": null, "status": "draft", "id": "d1556d00-8ebc-507a-bf69-64f85ab8c866"}, {"name": "杨宪（朱元璋儒士）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1356年朱元璋录用的儒士，奉使张士诚而被扣留；与旧南宋使金副使杨宪分开。", "biography": null, "status": "draft", "id": "0b8375cf-8092-5291-8774-008709bac291"}, {"name": "定定（元镇江平章）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1356年镇江战死。", "biography": null, "status": "draft", "id": "041c5cd9-bd57-5034-9f74-4e5a7d029b96"}, {"name": "耿炳文", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年随朱元璋于和州。", "biography": null, "status": "draft", "id": "348f31d6-f709-5dde-a5f7-f84796bfa663"}, {"name": "拜布哈（元宁国守臣）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1357年守城后降吴。", "biography": null, "status": "draft", "id": "e84a8ad1-8b53-5a01-b918-6817bdb96127"}, {"name": "赵继祖（郭子兴军诈使）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年诈为元使参与取和阳。", "biography": null, "status": "draft", "id": "beba6b9c-807c-54dd-bc22-18d83f839b94"}, {"name": "胡大海", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "吴将，常州夹击援军。", "biography": null, "status": "draft", "id": "9608d085-9e6c-528f-bbb3-143306d2efb9"}, {"name": "巴斯尔布哈（元徽州元帅）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1357年守徽州败于胡大海。", "biography": null, "status": "draft", "id": "bef3a141-edff-5cfb-985b-9c4801af72b9"}, {"name": "缪大亨", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1353年受花云夜袭后率二万人降朱元璋。", "biography": null, "status": "draft", "id": "c1e8abe5-f674-58a9-bf7c-e6b174d606c6"}, {"name": "张明鉴", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "青军首领，聚淮西暴掠，1357年扬州降吴。", "biography": null, "status": "draft", "id": "1ebdaec7-f2d8-5257-aec1-125bf82f9784"}, {"name": "明玉珍", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "随州人，从徐寿辉，1357年领舟取重庆。", "biography": null, "status": "draft", "id": "4e68200c-5dfc-5811-96fa-2de59fb619e3"}, {"status": "draft", "name": "徐寿辉", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "罗田人，原贩布，1351年在蕲黄以红巾起兵，被推为主，后建天完称帝。", "biography": null, "id": "168b2da9-205f-5285-b0b0-4618e5ef57a4"}, {"status": "draft", "name": "郭子兴", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "定远人，1352年聚壮士称元帅据濠州，留用朱元璋，后将马公托孤养女嫁之。", "biography": null, "id": "1496aa3f-23c8-51d2-bbe6-07e3bfda07bd"}, {"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "徐达", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "濠州人，1353年随朱元璋南略。", "biography": null, "status": "draft", "id": "0f28446e-78b0-5db1-9677-98777005803e"}, {"name": "汤和", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年夺桥取和阳，后从朱渡江。", "biography": null, "status": "draft", "id": "76a3c1b3-e175-593d-99d7-63da30cef072"}, {"name": "张士诚", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "白驹场盐民，率众起兵，陷高邮称诚王建周。", "biography": null, "status": "draft", "id": "7fbe0af4-cc39-5fb7-9fa8-c94e110ad986"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱谋诈元军夺和阳", "description": "朱元璋献计伪造庐州义军装束，以张天祐赵继祖三千诈为送赏使，耿再成万军后应。张误约致耿先战败，后张撞归军追至小西门，汤和断索夺桥入城，额森特穆尔夜逃。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "63ce269b-4cbb-581d-9587-b81329d3fd61"}, {"title": "朱慑来使后统和阳归被掠妇", "description": "郭误以张军失、又闻元使招，朱恐杀使促敌来，威吓后放，随即领军至已取和阳受命总军。诸将不服，汤和独遵，李善长调护。朱命归还被掠妇女，民喜。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "32ffe190-1fe8-5668-b72a-23af9c26894e"}, {"title": "郭子兴卒天叙继帅", "description": "本书记郭子兴因与孙德崖相争而饮恨去世，不据此补现代病因。众人推其长子天叙为元帅；孙德崖欲代统其军，天叙写信邀朱元璋相助。此明确长子不自动回填211未名求援的儿子。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8927ac15-7df4-55e7-8154-cba78517cfa9"}, {"title": "韩林儿立小明王宋龙凤", "description": "刘福通等迎韩林儿立为皇帝，又号小明王，都亳州，国号宋、年号龙凤。韩林儿母杨氏尊太后；杜遵道、盛文郁任相，罗文素、刘福通任平章，刘六知枢密院事；拆太清宫木材建宫。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9d57bfd9-6a84-553b-a404-518f63a5ef72"}, {"title": "郭天叙朱张受宋军帅号", "description": "张天祐自亳州带回杜遵道檄文，授郭天叙都元帅、张天祐右副、朱元璋左副。朱元璋初欲不受，后借宋为声援，采用龙凤纪年，军务实际不受其节制。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "14e64441-8975-5395-bdc3-77640f07fa19"}, {"title": "常遇春率众来归求先驱", "description": "常遇春不满旧主刘聚只务劫掠、无远图，率十余人投奔朱元璋，求任先锋。朱元璋先疑其因饥而来，令待渡江取太平后再从军，未在此刻即授先锋。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9734bf7a-ebd7-5a00-bc29-1b79e43d058a"}, {"title": "巢湖舟军归朱破峪溪", "description": "赵普胜俞通海因与左君弼隙欲附朱。朱亲导舟借雨涨出小港，赵中途叛去，余船归。朱先拘善舟十九人教军，廖永安张得胜俞通海破曼济哈雅峪溪，继定渡江先取采石策。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9b504881-4026-505a-8138-0a51a6bb5130"}, {"title": "朱渡江常遇春先登取采石", "description": "朱元璋与廖永安引舟向牛渚，常遇春先登驱退守军，诸军继进，攻取采石，沿江诸垒来附。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "088acd4c-bb9d-5c60-ae30-a2ae22cf425a"}, {"title": "朱断缆进太平俘纳克楚", "description": "朱元璋不准诸将取物返和州，命斩缆推舟顺流东下，转攻太平。鄂勒哲布哈、张旭弃城逃走，万户纳克楚被俘，未记将船全部毁弃。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33ca626d-3f04-5647-8f05-3737da48e809"}, {"title": "靳义死朱葬父老迎禁军掠", "description": "太平总管靳义赴水死，朱元璋认为其守义，备棺葬之。李习、陶安率父老迎接；李善长预作军禁榜，入城张贴，违令掠夺一卒被斩；陈迪所献财物分给将士。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "670bdb5d-98fd-5623-9198-1d86aabf7cd0"}, {"title": "太平改府任李习李善长汪广洋", "description": "朱元璋改太平路为府，任李习知府、李善长帅府都事、汪广洋令史。三帅名义上共署，而决策多出朱元璋，不省去郭、张阶段的名义领导。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c54fe5c8-500a-5e85-b1df-7ccc1fc1c772"}, {"title": "朱伏擒陈埜先", "description": "陈埜先率军攻太平，朱元璋遣徐达、邓愈、汤和迎战，并设伏襄城桥，陈埜先兵败被俘。曼济哈雅水军截江是同时背景，不说他本人在此被俘。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a6faddf4-2e6a-592e-9320-3e6c8bef3697"}, {"title": "陈杀郭天叙张天祐朱独帅", "description": "郭天叙、张天祐攻集庆，陈埜先表面同攻，却诱杀郭天叙，擒张天祐送福寿杀害。二帅死后，诸将推朱元璋为都元帅。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ff5a372c-d2fd-5b50-8285-643ca396c7de"}, {"title": "朱释纳克楚北归", "description": "朱元璋厚待纳克楚后见其不乐，念其各为旧主且家属在，放北归。纳为穆呼哩裔孙。", "start_year": 1355, "end_year": 1355, "time_original": "《续资治通鉴》卷212；本事原载纪年折合公元1355年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "00ffb8c7-0e5b-5344-9ab3-b66ae71068a7"}, {"title": "常遇春采石火舰败曼军", "description": "常遇春以正奇兵相配，在采石纵火焚连舰，曼济哈雅仅身免，江防扼制渐衰。", "start_year": 1356, "end_year": 1356, "time_original": "《续资治通鉴》卷213；本事原载纪年折合公元1356年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2837245b-6b89-52bd-9947-fe01c6e5cfe6"}, {"title": "朱元璋攻破陈兆先军营并安抚降兵", "description": "朱元璋率军攻破陈兆先营，俘获陈兆先，接纳其三万六千人，选五百勇士作宿卫。降兵疑惧，朱元璋让他们环榻而睡，屏退旧人，只留冯国用在旁，解甲安寝到天亮，降兵才安心。", "start_year": 1356, "end_year": 1356, "time_original": "《续资治通鉴》卷213；本事原载纪年折合公元1356年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fda44472-4669-51f7-950f-3630a5349806"}, {"title": "集庆破福寿等战死", "description": "冯国用率五百人率先攻入敌阵，在蒋山击败官军并逼近城下，福寿督兵多次失利，集庆城破后仍在巷中作战，坐在凤凰台下胡床上拒绝离去。达尼达斯留下与他一同死难，治书侍御史贺方也死难。", "start_year": 1356, "end_year": 1356, "time_original": "《续资治通鉴》卷213；本事原载纪年折合公元1356年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "50dc7174-52f4-5cd9-9604-aade5dc28002"}, {"title": "朱元璋改集庆为应天府，安民纳降", "description": "集庆城破，曼济哈雅逃投张士诚，康茂才等率众投降，朱元璋得到军民五十余万，并非五十余万士兵。他召父老官吏安抚，礼葬福寿，改集庆为应天府，设天兴、建康翼统军大元帅府，任廖永安统军、赵忠守太平，又录用夏煜、孙炎、杨宪等儒士。", "start_year": 1356, "end_year": 1356, "time_original": "《续资治通鉴》卷213；本事原载纪年折合公元1356年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b78c5a65-7b7d-5230-8b4d-a2647b24cdf6"}, {"title": "徐达攻取镇江、金坛和丹阳", "description": "朱元璋责备诸将纵兵，原欲处刑，李善长营救使其免罪。朱元璋命徐达进攻镇江，严禁焚掠杀戮。徐达取城，鄂勒哲逃走，段武、定定战死；徐达军入城纪律严明，继取金坛、丹阳。镇江改江淮府，徐达、汤和任统军元帅镇守。", "start_year": 1356, "end_year": 1356, "time_original": "《续资治通鉴》卷213；本事原载纪年折合公元1356年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "01fdc558-a966-50cc-a70d-c9811390fd2d"}, {"title": "建康军取广德邓愈守", "description": "建康军取广德改广兴府，邓愈镇守。", "start_year": 1356, "end_year": 1356, "time_original": "《续资治通鉴》卷213；本事原载纪年折合公元1356年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7fda2772-69bd-5d45-b665-3b3208cff228"}, {"title": "诸将奉朱元璋为吴国公，遥尊韩林儿", "description": "建康诸将奉朱元璋为吴国公，设江南行省并由他总理省务。朱元璋因韩林儿自称宋后而遥奉为主，文书、除授采用龙凤纪年；仅据这种名义，不推定军务始终实受韩节制。", "start_year": 1356, "end_year": 1356, "time_original": "《续资治通鉴》卷213；本事原载纪年折合公元1356年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6fc750ed-7dff-5773-8eb7-9ea4fb9371bf"}, {"title": "徐达围攻常州，在龙潭击败援军", "description": "张士诚派舟师进攻镇江，朱元璋命徐达反攻常州，并增兵三万。徐达、汤和、张彪分军围城；张士诚遣数万援军来，徐达退离城十八里设伏，命王均用以铁骑奇袭，在龙潭击败援军。", "start_year": 1356, "end_year": 1356, "time_original": "《续资治通鉴》卷213；本事原载纪年折合公元1356年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ab48f7b3-75f8-59d3-95ab-ea5d2b5c0a6e"}, {"title": "朱元璋赴江淮府祭孔、劝农和设水寨", "description": "朱元璋赴江淮府，先祭孔庙，遣儒士劝耕桑，筑城壕，命总管徐忠设金山水寨，随后返回，不久将江淮府改为镇江府。", "start_year": 1356, "end_year": 1356, "time_original": "《续资治通鉴》卷213；本事原载纪年折合公元1356年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3baa60e0-157b-56eb-ae6a-d326f52fc1ce"}, {"title": "耿炳文、刘成攻克长兴，获舟并受降", "description": "朱元璋遣耿炳文、刘成由广德进取长兴，击败赵打虎并追到城门，继而克城，获战船三百余艘，擒李福安、达实曼。义兵万户蒋毅率二百人投降。", "start_year": 1357, "end_year": 1357, "time_original": "《续资治通鉴》卷213；本事原载纪年折合公元1357年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d911356d-d37a-53a7-a24a-9bf8b18532ee"}, {"title": "徐达克常州再下马驮沙", "description": "常州纳叛军后人多粮少，徐达急攻，吕珍夜遁城破，改常州府。徐与常遇春桑世杰再取马驮沙。", "start_year": 1357, "end_year": 1357, "time_original": "《续资治通鉴》卷213；本事原载纪年折合公元1357年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "344370ae-3659-5be6-b8d5-0e2c21136049"}, {"title": "朱元璋督攻宁国，朱亮祖被擒后获释", "description": "徐达、常遇春攻宁国，谢国玺逃走，拜布哈、杨仲英拒守。常遇春中箭后裹伤续战。朱元璋亲至督师，令造飞车推进，守将请降；朱文贵杀妻妾后自刎，朱亮祖被擒。朱亮祖此前曾降又叛；这次被缚到后，朱元璋问话，听其回答后壮其气概，予以释放。", "start_year": 1357, "end_year": 1357, "time_original": "《续资治通鉴》卷213；本事原载纪年折合公元1357年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8fee4e7c-c30c-58d9-b684-4c08f910a2b0"}, {"title": "上元、宁国和句容献麦", "description": "五月，上元、宁国和句容献上被视为祥瑞的麦子。", "start_year": 1357, "end_year": 1357, "time_original": "至正十七年五月", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0f794968-8167-5853-98ce-b3023e33e8e6"}, {"title": "赵继祖等攻取江阴，吴良镇守", "description": "朱元璋遣赵继祖、郭天禄、吴良进攻江阴，在风雨中击溃秦望山守军，占领山地，随后进攻西门克城，命吴良镇守。", "start_year": 1357, "end_year": 1357, "time_original": "《续资治通鉴》卷213；本事原载纪年折合公元1357年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "461e6a12-561c-504f-bdae-5f124368158b"}, {"title": "胡大海攻下徽州，吴讷败后自杀", "description": "胡大海等攻下绩溪后，进攻徽州，击败守将巴斯尔布哈、吴讷，攻入城中。吴讷等退守遂安，胡大海追至白际岭，再次将其击败。吴讷自杀，徽州属县随后相继被攻下。", "start_year": 1357, "end_year": 1357, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1357年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "98113a96-e7bb-597a-8665-1e9d31f423f8"}, {"title": "常遇春、廖永安等攻下池州并击败援军", "description": "常遇春率廖永安等从铜陵进攻池州。廖永安行至离城十里处时，常遇春与吴国宝率舟师抵达城下合攻，攻破北门，入城擒杀洪元帅，俘获魏寿、徐天麟等将领。傍晚，元军又以数百艘战船来战，再次被击败，池州遂被攻下。", "start_year": 1357, "end_year": 1357, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1357年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "36f97534-c203-5057-ac4d-b999e258961a"}, {"title": "缪大亨攻下扬州，张明鉴率众归降", "description": "朱元璋在大通江检阅军队后，命缪大亨进攻扬州。张明鉴率数万人投降。朱元璋设置淮海翼元帅府，命张德麟、耿再成驻守，并以李德林为淮海知府。当时城内仅剩十八户人家，李德林认为旧城空旷难守，便截取西南一角，筑城驻守。", "start_year": 1357, "end_year": 1357, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1357年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a81a355d-c5c6-5a24-9b25-f52b862c5cb5"}, {"title": "朱元璋释放轻罪和重罪囚犯", "description": "朱元璋因战乱尚未平定、百姓刚刚归附，下令释放轻罪和重罪囚犯。", "start_year": 1357, "end_year": 1357, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1357年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "26f90808-6aae-52cc-a171-73e9f8f10efa"}, {"title": "明玉珍攻取重庆", "description": "徐寿辉部将明玉珍攻取重庆并据守。此前，杨汉险遭重庆左丞相鄂勒哲图谋害，逃走后遇到明玉珍，向他诉说经过，并建议进取重庆。戴寿也劝明玉珍出兵。明玉珍采纳建议，攻下重庆，鄂勒哲图逃走。明玉珍入城后禁止侵掠。", "start_year": 1357, "end_year": 1357, "time_original": "《续资治通鉴》卷214；本事原载纪年折合公元1357年，具体月日依引文。", "dynasty": "元及同时诸政权", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "460a1d64-97f8-56fb-8e13-51a28eaad269"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

