SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "person", "field_path": "description", "claim_text": "张天祐奉郭子兴之命攻取和州。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000358；元末，原文未载这项身份的具体年月", "note": "原文：子興用太祖計，遣張天祐等拔和州；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "2f417f02-98b6-5bbc-8c6d-8f2e92d08b53", "subject_id": "5bc1cc3a-538d-55e0-a5c5-80feaeaf4ede", "source_id": "c0b131be-e7f9-5754-b7e5-5f118f0227eb"}, {"subject_table": "person", "field_path": "description", "claim_text": "郭子兴的儿子郭天叙获授都元帅。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000359；元末，原文未载这项身份的具体年月", "note": "原文：檄子興子天敍為都元帥；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "f37a7fc8-533a-5845-ac79-e6b7eab6c031", "subject_id": "cee66f31-f5f1-54d2-ac4b-cd2a49fdb40e", "source_id": "83d760fa-0c32-5ce9-9169-29bb780cd724"}, {"subject_table": "person", "field_path": "description", "claim_text": "刘福通拥立韩山童的儿子韩林儿。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000359；元末，原文未载这项身份的具体年月", "note": "原文：劉福通迎立韓山童子林兒於亳；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "b622ad7e-01c4-5621-80e9-fd483c0280d5", "subject_id": "15a71da9-cd6f-5a0b-ba68-144469ebde18", "source_id": "83d760fa-0c32-5ce9-9169-29bb780cd724"}, {"subject_table": "person", "field_path": "description", "claim_text": "韩山童的儿子韩林儿获刘福通拥立。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000359；元末，原文未载这项身份的具体年月", "note": "原文：劉福通迎立韓山童子林兒於亳；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "885ee780-e4b4-5e1a-bfdd-abf293bf653c", "subject_id": "8c55f661-a30a-53e7-840c-8dabfaa2a6ba", "source_id": "83d760fa-0c32-5ce9-9169-29bb780cd724"}, {"subject_table": "person", "field_path": "description", "claim_text": "刘福通在亳州拥立韩林儿。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000359；元末，原文未载这项身份的具体年月", "note": "原文：劉福通迎立韓山童子林兒於亳；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "1f106f1b-1afa-5697-8076-3bb5f349e33a", "subject_id": "bb43c0fa-e764-55ad-a47a-f24d9349e961", "source_id": "83d760fa-0c32-5ce9-9169-29bb780cd724"}, {"subject_table": "person", "field_path": "description", "claim_text": "至正十五年四月，常遇春前来投奔朱元璋。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000360；元末，原文未载这项身份的具体年月", "note": "原文：夏四月，常遇春來歸。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "3d3b543e-8781-5fbc-bc13-a671ca8f12e6", "subject_id": "51d50a75-07e1-574f-b22d-1fded66288ff", "source_id": "6c923def-811c-53ac-8a0f-b3737f30527f"}, {"subject_table": "person", "field_path": "description", "claim_text": "廖永安和俞通海率领巢湖水军归附朱元璋。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000361；元末，原文未载这项身份的具体年月", "note": "原文：巢湖帥廖永安、俞通海以水軍千艘來附；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "3fef51b7-9a4a-5298-9f74-d56a391ca1e3", "subject_id": "473be43f-6bda-56e2-b78d-5dec54725ac0", "source_id": "10e0e508-f134-5351-bd3e-e7241c792306"}, {"subject_table": "person", "field_path": "description", "claim_text": "俞通海与廖永安率巢湖水军归附朱元璋。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000361；元末，原文未载这项身份的具体年月", "note": "原文：巢湖帥廖永安、俞通海以水軍千艘來附；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "33c1ea4c-4fea-5407-8b13-f8a80ccb6d40", "subject_id": "eff73aa1-e4e3-5022-b155-bf9d88812371", "source_id": "10e0e508-f134-5351-bd3e-e7241c792306"}, {"subject_table": "person", "field_path": "description", "claim_text": "本纪称元中丞蛮子海牙。他扼守巢湖舟师出口，在峪溪口被击败。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000361；元末，原文未载这项身份的具体年月", "note": "原文：元中丞蠻子海牙扼銅城閘、馬場河諸隘，巢湖舟師不得出。忽大雨，太祖喜曰：「天助我也。」遂乘水漲從小港縱舟還，因擊海牙於峪溪口，大敗之；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "2728fa76-7d8f-51e3-978e-8f16c2a6e30e", "subject_id": "f03aa5ed-5240-53e8-93d7-77707427f880", "source_id": "10e0e508-f134-5351-bd3e-e7241c792306"}, {"subject_table": "person", "field_path": "description", "claim_text": "本纪称纳哈出。他任元朝万户，太平被朱元璋攻取时被俘。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000362；元末，原文未载这项身份的具体年月", "note": "原文：遂乘勝拔太平，執萬戶納哈出。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "1e20b649-180c-5659-8962-0fa50b524ef6", "subject_id": "89f87003-83bd-5c55-b910-1c5e3f351489", "source_id": "dd58019c-ffe3-5ce9-96ff-da041d2ede9c"}, {"subject_table": "person", "field_path": "description", "claim_text": "靳义是元朝总管，太平失守时投水身亡。朱元璋后来按礼安葬了他。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000362；元末，原文未载这项身份的具体年月", "note": "原文：總管靳義赴水死，太祖曰：「義士也」，禮葬之。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "b1138ce7-9537-5e37-9fc6-d33d323a359d", "subject_id": "45ed38fa-42f1-5777-9ec7-0d7a6001cc3c", "source_id": "dd58019c-ffe3-5ce9-96ff-da041d2ede9c"}, {"subject_table": "person", "field_path": "description", "claim_text": "朱元璋设置太平兴国翼元帅府后，任陶安参理幕府事务。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000362；元末，原文未载这项身份的具体年月", "note": "原文：置太平興國翼元帥府，自領元帥事，召陶安參幕府事；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "99a391c8-c54f-5ded-b838-e34788e594ea", "subject_id": "e532b07c-1439-59f2-9d9e-c03e6fe1c439", "source_id": "dd58019c-ffe3-5ce9-96ff-da041d2ede9c"}, {"subject_table": "person", "field_path": "description", "claim_text": "朱元璋改太平路为府后，任李习为知府。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000362；元末，原文未载这项身份的具体年月", "note": "原文：改路曰府。置太平興國翼元帥府，自領元帥事，召陶安參幕府事，李習為知府。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "5db80a2b-6566-52cc-8cb8-8666592f8119", "subject_id": "01e6f626-bb8d-5d6d-823c-a0bd2f17e0bb", "source_id": "dd58019c-ffe3-5ce9-96ff-da041d2ede9c"}, {"subject_table": "person", "field_path": "description", "claim_text": "陈埜先所部进攻太平，遭朱元璋派兵反击。陈埜先被俘，军队归降。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000362；元末，原文未载这项身份的具体年月", "note": "原文：陳埜先水軍帥康茂才以數萬眾攻城。太祖遣徐達、鄧愈、湯和逆戰，別將潛出其後，夾擊之，擒埜先并降其眾；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "2f1fb21c-90d4-5b3d-89d1-9175ea2785fb", "subject_id": "e162f293-f1f5-514d-a501-4b1a3b7f54fb", "source_id": "dd58019c-ffe3-5ce9-96ff-da041d2ede9c"}, {"subject_table": "person", "field_path": "description", "claim_text": "康茂才率领陈埜先的水军进攻太平。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000362；元末，原文未载这项身份的具体年月", "note": "原文：陳埜先水軍帥康茂才以數萬眾攻城。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "8a6589e6-5834-5c4b-8d03-b979a1e56985", "subject_id": "f04c265d-38f9-5b72-9c39-567870658cd2", "source_id": "dd58019c-ffe3-5ce9-96ff-da041d2ede9c"}, {"subject_table": "person", "field_path": "description", "claim_text": "邓愈和徐达、汤和奉朱元璋之命迎击陈埜先所部。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000362；元末，原文未载这项身份的具体年月", "note": "原文：太祖遣徐達、鄧愈、湯和逆戰；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "c32bee22-b80a-5c3a-a237-ab090c9c394a", "subject_id": "5fbf3347-c8f3-5eaa-aa83-d0681e64b192", "source_id": "dd58019c-ffe3-5ce9-96ff-da041d2ede9c"}, {"subject_table": "person", "field_path": "description", "claim_text": "本纪称兆先为陈埜先的侄子。陈埜先死后，兆先收拢余部驻扎方山。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000363；元末，原文未载这项身份的具体年月", "note": "原文：埜先尋為民兵所殺，從子兆先收其眾，屯方山；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "5cf77a8a-875b-5c70-9d59-d7d1604d05c9", "subject_id": "327fe3e3-2043-5c74-9aaa-aa96fbd51ac3", "source_id": "2a5cbfd4-a77c-534f-83cd-4f2976a2ac16"}, {"subject_table": "person", "field_path": "description", "claim_text": "集庆争夺战中，元御史大夫福寿战死。朱元璋入城后礼葬福寿。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000367；元末，原文未载这项身份的具体年月", "note": "原文：元御史大夫福壽力戰死之；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "38b85698-dec1-550a-a9dc-68543b6601f1", "subject_id": "988fcd01-fe5e-558d-b908-845e059916ba", "source_id": "57b6147a-d5d7-575f-b847-ebc3d68ae91a"}, {"subject_table": "person", "field_path": "description", "claim_text": "朱元璋攻取集庆后录用夏煜。", "citation": "《明史》卷1·本纪第一·太祖一·mingshi-2f603db3d81e-p000367；元末，原文未载这项身份的具体年月", "note": "原文：辟夏煜、孫炎、楊憲等十餘人；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft"